/**
 * Published monthly ADM2 mean radiance from World Bank Space2Stats.
 * These rows are never generated by the front-end; the sync script reads
 * published source data and stores an auditable small local JSON extract.
 */
export const WORLD_BANK_BLACK_MARBLE_URL = 'https://datacatalog.worldbank.org/search/dataset/0066940/space2stats-monthly-annual-black-marble-nighttime-lights';
export type WorldBankDistrictPoint={
  district:string;
  period:string;
  radiance:number;
  validPixels:number|null;
  quality0Fraction:number|null;
};
export type WorldBankDistrictSeries={district:string;points:WorldBankDistrictPoint[]};
export type WorldBankBlackMarbleData={
  source:string;sourceUrl:string;license:string;datasetId:string;
  periodStart:string;periodEnd:string;statistic:string;qualityNote:string;
  sourceYears:number[];generatedAtUtc:string;
  failedYears?:number[];importWarnings?:{year:number;reason:string}[];
  excludedConflicts?:{district:string;period:string;reason:string;sourceRecords?:unknown[]}[];
  districts:WorldBankDistrictSeries[];
};
export function parseWorldBankDistrictData(data:unknown):WorldBankBlackMarbleData|null {
  if(!data||typeof data!=='object')return null;
  const d=data as Partial<WorldBankBlackMarbleData>;
  if(d.datasetId!=='0066940'||!Array.isArray(d.districts)||!d.districts.length)return null;
  const ok=d.districts.every(s=>s&&typeof s.district==='string'&&Array.isArray(s.points)&&s.points.every(p=>
    typeof p.period==='string'&&/^20\d{2}-(0[1-9]|1[0-2])$/.test(p.period)&&
    typeof p.radiance==='number'&&Number.isFinite(p.radiance)&&p.radiance>=0&&
    (p.validPixels===null||(Number.isSafeInteger(p.validPixels)&&p.validPixels>=0))&&
    (p.quality0Fraction===null||(typeof p.quality0Fraction==='number'&&p.quality0Fraction>=0&&p.quality0Fraction<=1))
  ));
  return ok?d as WorldBankBlackMarbleData:null;
}
